import java.util.Iterator;
import java.util.NoSuchElementException;

public class CustomIterableDemo {
    // Custom domain container implementing Iterable<String>
    static class DevTeam implements Iterable<String> {
        private final String[] members;
        private int count = 0;

        public DevTeam(int capacity) {
            this.members = new String[capacity];
        }

        public void addMember(String name) {
            if (count < members.length) {
                members[count++] = name;
            }
        }

        @Override
        public Iterator<String> iterator() {
            return new Iterator<>() {
                private int index = 0;

                @Override
                public boolean hasNext() {
                    return index < count;
                }

                @Override
                public String next() {
                    if (!hasNext()) {
                        throw new NoSuchElementException("No more team members");
                    }
                    return members[index++];
                }
            };
        }
    }

    public static void main(String[] args) {
        DevTeam team = new DevTeam(5);
        team.addMember("Alice (Lead)");
        team.addMember("Bob (Backend)");
        team.addMember("Charlie (DevOps)");

        // Native enhanced for-each loop over our custom domain class!
        System.out.println("Active Development Team Roster:");
        for (String member : team) {
            System.out.println(" -> " + member);
        }
    }
}
// Expected Output:
// Active Development Team Roster:
//  -> Alice (Lead)
//  -> Bob (Backend)
//  -> Charlie (DevOps)

