import java.util.Iterator;
import java.util.List;
import java.util.NoSuchElementException;
import java.util.function.Predicate;

public class FilteredIterable<T> implements Iterable<T> {
    private final Iterable<T> source;
    private final Predicate<T> predicate;

    public FilteredIterable(Iterable<T> source, Predicate<T> predicate) {
        this.source = source;
        this.predicate = predicate;
    }

    @Override
    public Iterator<T> iterator() {
        return new Iterator<>() {
            private final Iterator<T> underlying = source.iterator();
            private T nextElement = null;
            private boolean hasNextFound = false;

            @Override
            public boolean hasNext() {
                if (hasNextFound) return true;
                while (underlying.hasNext()) {
                    T candidate = underlying.next();
                    if (predicate.test(candidate)) {
                        nextElement = candidate;
                        hasNextFound = true;
                        return true;
                    }
                }
                return false;
            }

            @Override
            public T next() {
                if (!hasNext()) throw new NoSuchElementException();
                hasNextFound = false;
                T result = nextElement;
                nextElement = null;
                return result;
            }
        };
    }

    public static void main(String[] args) {
        List<Integer> nums = List.of(1, 2, 3, 4, 5, 6);
        FilteredIterable<Integer> evens = new FilteredIterable<>(nums, n -> n % 2 == 0);
        for (int n : evens) {
            System.out.print(n + " ");
        }
        System.out.println();
    }
}

