import java.util.Iterator;
import java.util.List;
import java.util.NoSuchElementException;

public class CompositeIterable<T> implements Iterable<T> {
    private final Iterable<T> first;
    private final Iterable<T> second;

    public CompositeIterable(Iterable<T> first, Iterable<T> second) {
        this.first = first;
        this.second = second;
    }

    @Override
    public Iterator<T> iterator() {
        return new Iterator<>() {
            private final Iterator<T> it1 = first != null ? first.iterator() : null;
            private final Iterator<T> it2 = second != null ? second.iterator() : null;

            @Override
            public boolean hasNext() {
                if (it1 != null && it1.hasNext()) return true;
                return it2 != null && it2.hasNext();
            }

            @Override
            public T next() {
                if (it1 != null && it1.hasNext()) return it1.next();
                if (it2 != null && it2.hasNext()) return it2.next();
                throw new NoSuchElementException();
            }
        };
    }

    public static void main(String[] args) {
        List<String> l1 = List.of("A", "B");
        List<String> l2 = List.of("C", "D");
        for (String s : new CompositeIterable<>(l1, l2)) {
            System.out.print(s + " ");
        }
        System.out.println();
    }
}
